import * as THREE from 'three';
import { T } from './textures.js';

const matCache = new Map();
function mat(key, params) {
  if (!matCache.has(key)) matCache.set(key, new THREE.MeshStandardMaterial(params));
  return matCache.get(key);
}

const boxGeo = new THREE.BoxGeometry(1, 1, 1);
const cylGeo = new THREE.CylinderGeometry(1, 1, 1, 12);

export function box(w, h, d, material, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(boxGeo, material);
  m.scale.set(w, h, d);
  m.position.set(x, y, z);
  m.castShadow = false;
  m.receiveShadow = false;
  return m;
}

export function cyl(rt, rb, h, material, x = 0, y = 0, z = 0, seg = 12) {
  const m = new THREE.Mesh(cylGeo, material);
  m.scale.set(rt, h, rt);
  if (rb !== rt) m.scale.x = m.scale.z = (rt + rb) / 2;
  m.position.set(x, y, z);
  return m;
}

export function makeLabel(text, opts = {}) {
  const { color = '#8dffb2', bg = 'rgba(4,10,7,.85)', size = 256, h = 64, font = 'bold 34px Courier New' } = opts;
  const c = document.createElement('canvas');
  c.width = size; c.height = h;
  const g = c.getContext('2d');
  g.fillStyle = bg; g.fillRect(0, 0, size, h);
  g.strokeStyle = color; g.lineWidth = 3; g.strokeRect(3, 3, size - 6, h - 6);
  g.fillStyle = color; g.font = font; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(text, size / 2, h / 2 + 2);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const m = new THREE.SpriteMaterial({ map: tex, transparent: true, depthWrite: false });
  const sprite = new THREE.Sprite(m);
  sprite.scale.set(size / h * 0.52, 0.52, 1);
  return sprite;
}

export function makeSignPlane(text, w = 0.55, h = 0.45, color = '#ff5566') {
  const c = document.createElement('canvas');
  c.width = 256; c.height = 256;
  const g = c.getContext('2d');
  g.fillStyle = '#0a0d0b'; g.fillRect(0, 0, 256, 256);
  g.strokeStyle = color; g.lineWidth = 12; g.strokeRect(10, 10, 236, 236);
  g.fillStyle = color; g.font = 'bold 150px Courier New'; g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(text, 128, 138);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  const m = new THREE.MeshBasicMaterial({ map: tex, transparent: true });
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), m);
  return mesh;
}

export function makePerson(opts = {}) {
  const {
    skin = 0xc79b7d, shirt = 0x3d5a80, pants = 0x2a3040, hair = 0x2a1f1a,
    height = 1.0, backpack = null, female = false, tie = null, name = ''
  } = opts;
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);
  const s = height;

  const skinMat = mat('skin' + skin, { color: skin, roughness: 0.85 });
  const shirtMat = mat('shirt' + shirt, { color: shirt, roughness: 0.9 });
  const pantsMat = mat('pants' + pants, { color: pants, roughness: 0.95 });
  const hairMat = mat('hair' + hair, { color: hair, roughness: 0.8 });
  const shoeMat = mat('shoe', { color: 0x161619, roughness: 0.7 });

  const hips = new THREE.Group();
  hips.position.y = 0.86 * s;
  body.add(hips);

  const torso = box(0.46, 0.62, 0.26, shirtMat, 0, 0.3 * s, 0);
  hips.add(torso);
  const neck = cyl(0.07, 0.07, 0.1, skinMat, 0, 0.64 * s, 0);
  hips.add(neck);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.155, 12, 10), skinMat);
  head.position.set(0, 0.78 * s, 0);
  head.scale.set(1, 1.1, 0.95);
  hips.add(head);
  const hairMesh = new THREE.Mesh(new THREE.SphereGeometry(0.162, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.55), hairMat);
  hairMesh.position.set(0, 0.80 * s, 0);
  if (female) hairMesh.scale.set(1.02, 1.15, 1.12);
  hips.add(hairMesh);
  if (female) {
    const pony = box(0.13, 0.36, 0.12, hairMat, 0, 0.62 * s, -0.13 * s);
    hips.add(pony);
  }
  // eyes (subtle)
  const eyeMat = mat('eyes', { color: 0x171b20 });
  [-0.055, 0.055].forEach(x => {
    const e = new THREE.Mesh(new THREE.SphereGeometry(0.018, 6, 6), eyeMat);
    e.position.set(x, 0.80 * s, 0.135);
    hips.add(e);
  });
  if (tie) {
    const tieM = box(0.06, 0.28, 0.02, mat('tie' + tie, { color: tie, roughness: 0.7 }), 0, 0.35 * s, 0.135);
    hips.add(tieM);
  }
  if (backpack) {
    const bp = box(0.34, 0.4, 0.16, mat('bp' + backpack, { color: backpack, roughness: 0.9 }), 0, 0.34 * s, -0.2);
    hips.add(bp);
    const strap = box(0.05, 0.3, 0.03, mat('strap', { color: 0x1c1c22 }), -0.12, 0.4 * s, 0.13);
    hips.add(strap);
    const strap2 = strap.clone(); strap2.position.x = 0.12; hips.add(strap2);
  }

  function arm(side) {
    const g = new THREE.Group();
    g.position.set(side * 0.29, 0.56 * s, 0);
    const upper = box(0.11, 0.32, 0.12, shirtMat, 0, -0.16 * s, 0);
    g.add(upper);
    const fore = box(0.095, 0.28, 0.1, skinMat, 0, -0.43 * s, 0);
    g.add(fore);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.055, 8, 8), skinMat);
    hand.position.set(0, -0.58 * s, 0);
    g.add(hand);
    hips.add(g);
    return g;
  }
  const armL = arm(-1), armR = arm(1);

  function leg(side) {
    const g = new THREE.Group();
    g.position.set(side * 0.13, 0.86 * s, 0);
    const upper = box(0.145, 0.44, 0.16, pantsMat, 0, -0.22 * s, 0);
    g.add(upper);
    const lower = box(0.12, 0.36, 0.13, pantsMat, 0, -0.58 * s, 0);
    g.add(lower);
    const shoe = box(0.145, 0.1, 0.27, shoeMat, 0, -0.79 * s, 0.05);
    g.add(shoe);
    hips.add(g);
    return g;
  }
  const legL = leg(-1), legR = leg(1);

  if (name) {
    const lbl = makeLabel(name, { color: '#cfe9da', bg: 'rgba(3,8,6,.55)', size: 256, h: 64, font: 'bold 26px Courier New' });
    lbl.position.set(0, 1.85 * s, 0);
    lbl.scale.set(0.8, 0.2, 1);
    root.add(lbl);
    root.userData.nameSprite = lbl;
  }

  root.userData.parts = { body, hips, torso, head, hairMesh, armL, armR, legL, legR, height: s };
  return root;
}

export function makeKillerModel() {
  const root = new THREE.Group();
  const body = new THREE.Group();
  root.add(body);
  const skin = mat('killerSkin', { color: 0xb9c0b2, roughness: 0.95 });
  const suit = mat('killerSuit', { color: 0x1b1d1e, roughness: 0.9 });
  const shirtM = mat('killerShirt', { color: 0x3a3f41, roughness: 0.9 });
  const dark = mat('killerDark', { color: 0x0b0d0e, roughness: 0.8 });

  const hips = new THREE.Group(); hips.position.y = 1.18; body.add(hips);
  const torso = box(0.62, 0.86, 0.36, suit, 0, 0.38, 0); hips.add(torso);
  const shirt = box(0.3, 0.7, 0.04, shirtM, 0, 0.4, 0.19); hips.add(shirt);
  const tie = box(0.08, 0.5, 0.03, dark, 0, 0.36, 0.22); hips.add(tie);
  const neck = cyl(0.09, 0.11, 0.22, skin, 0, 0.86, 0); hips.add(neck);
  const head = new THREE.Mesh(new THREE.SphereGeometry(0.2, 12, 10), skin);
  head.scale.set(0.92, 1.18, 0.9); head.position.set(0, 1.06, 0.02); hips.add(head);
  // stretched jaw
  const jaw = box(0.2, 0.2, 0.2, skin, 0, 0.94, 0.06); hips.add(jaw);
  // eyes glow
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0xff3344 });
  const eyes = [];
  [-0.085, 0.085].forEach(x => {
    const e = new THREE.Mesh(new THREE.SphereGeometry(0.032, 8, 8), eyeMat);
    e.position.set(x, 1.08, 0.16); hips.add(e); eyes.push(e);
  });
  // smile
  const smile = box(0.18, 0.02, 0.02, dark, 0, 0.9, 0.18); hips.add(smile);

  function arm(side) {
    const g = new THREE.Group(); g.position.set(side * 0.38, 0.76, 0); hips.add(g);
    const upper = box(0.14, 0.5, 0.15, suit, 0, -0.24, 0); g.add(upper);
    const fore = box(0.12, 0.5, 0.13, suit, 0, -0.72, 0); g.add(fore);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.07, 8, 8), skin);
    hand.position.set(0, -0.98, 0); g.add(hand);
    return g;
  }
  const armL = arm(-1), armR = arm(1);

  // axe in right hand
  const axe = new THREE.Group();
  axe.position.set(0, -0.96, 0.02);
  const handle = cyl(0.035, 0.04, 1.05, mat('axeHandle', { color: 0x5b3a20, roughness: 0.85 }), 0, 0.28, 0);
  axe.add(handle);
  const bladeShape = new THREE.Shape();
  bladeShape.moveTo(0, 0);
  bladeShape.lineTo(0.34, 0.16);
  bladeShape.lineTo(0.34, 0.44);
  bladeShape.lineTo(0, 0.52);
  bladeShape.lineTo(-0.03, 0.26);
  bladeShape.closePath();
  const bladeGeo = new THREE.ExtrudeGeometry(bladeShape, { depth: 0.04, bevelEnabled: false });
  const blade = new THREE.Mesh(bladeGeo, mat('axeBlade', { color: 0x9ba2a6, roughness: 0.35, metalness: 0.85 }));
  blade.rotation.y = Math.PI / 2;
  blade.position.set(0, 0.62, 0.06);
  axe.add(blade);
  armR.add(axe);

  function leg(side) {
    const g = new THREE.Group(); g.position.set(side * 0.17, 0, 0);
    const upper = box(0.19, 0.56, 0.2, suit, 0, -0.28, 0); g.add(upper);
    const lower = box(0.16, 0.5, 0.17, suit, 0, -0.78, 0); g.add(lower);
    const shoe = box(0.18, 0.12, 0.34, dark, 0, -1.05, 0.06); g.add(shoe);
    hips.add(g); g.position.y = 0.02;
    return g;
  }
  const legL = leg(-1), legR = leg(1);

  root.userData.parts = { body, hips, head, armL, armR, legL, legR, axe, eyes };
  return root;
}

