    if (opts.quick) { card.querySelectorAll('.row').forEach(r => r.classList.add('on')); return; }
    const rowEls = [...card.querySelectorAll('.row')];
    for (const r of rowEls) {
      await sleep(opts.rowDelay || 240);
      r.classList.add('on');
    }
  },
  hideReportCard() { this.el['report-card'].classList.add('hidden'); },

  note(title, body) {
    this.el['note-title'].textContent = title;
    this.el['note-body'].textContent = body;
    this.el['note-popup'].classList.remove('hidden');
  },
  hideNote() { this.el['note-popup'].classList.add('hidden'); },

  setDown(on) {
    this.el['down-fx'].classList.toggle('on', on);
    this.el.app.classList.toggle('downed', on);
  },
  setDownSecs(s) { this.el['down-secs'].textContent = Math.max(0, Math.ceil(s)); },

  jumpscare(on) {
    this.el['jumpscare-fx'].classList.toggle('on', on);
    if (on) {
      this.el.app.classList.remove('shake'); void this.el.app.offsetWidth; this.el.app.classList.add('shake');
    }
  },

  showCine(on) {
    this.el['cine-ui'].classList.toggle('hidden', !on);
    this.el.app.classList.toggle('cinema', on);
    if (!on) {
      this.el['cine-subtitle-wrap'].classList.remove('show');
      this.el['cine-card'].classList.remove('show');
      this.el['cine-grade'].classList.remove('show');
    }
  },
  cineSubtitle(speaker, text, dur = 3.4) {
    this.el['cine-speaker'].textContent = speaker || '';
    this.el['cine-subtitle'].innerHTML = text;
    this.el['cine-subtitle-wrap'].classList.add('show');
    clearTimeout(this._cineSubTimer);
    this._cineSubTimer = setTimeout(() => this.el['cine-subtitle-wrap'].classList.remove('show'), dur * 1000);
  },
  cineClearSub() { this.el['cine-subtitle-wrap'].classList.remove('show'); },
  cineCard(kicker, title, align = 'left') {
    const c = this.el['cine-card'];
    c.classList.remove('center', 'left');
    c.classList.add(align === 'center' ? 'center' : 'left');
    this.el.cineKicker.textContent = kicker;
    this.el.cineTitle.textContent = title;
    c.classList.remove('show'); void c.offsetWidth; c.classList.add('show');
  },
  cineHideCard() { this.el['cine-card'].classList.remove('show'); },
  cineFlash() { const f = this.el['cine-flash']; f.classList.remove('fire'); void f.offsetWidth; f.classList.add('fire'); },
  cineFlare(on) { this.el['cine-flare'].classList.toggle('on', on); },
  cineLines(on) { this.el['cine-speedlines'].classList.toggle('on', on); },
  cineSkip(on) { this.el['cine-skip'].classList.toggle('show', on); },

  cineGrade(rows, opts = {}) {
    this.el.cgName.innerHTML = `STUDENT: <b>${opts.name || 'JAKE'}</b>`;
    this.el.cgRows.innerHTML = rows.map(r => `<div class="cg-row"><span class="subject">${r[0]}</span><span class="grade ${r[3] || ''}">${r[1]}</span></div>`).join('');
    this.el.cgStamp.textContent = opts.stamp || 'Z+';
    this.el.gradeEl.classList.remove('hidden', 'wrong');
    this.el.gradeEl.classList.add('show');
    if (opts.wrong) { void this.el.gradeEl.offsetWidth; this.el.gradeEl.classList.add('wrong'); }
  },
  cineGradeRow(i) {
    const rows = this.el.cgRows.querySelectorAll('.cg-row');
    if (rows[i]) rows[i].classList.add('on');
  },
  cineStamp() { this.el.cgStamp.classList.add('on'); },
  cineGradeHide() { this.el.gradeEl.classList.remove('show'); setTimeout(() => this.el.gradeEl.classList.add('hidden'), 420); },

  win(grade, stats, line) {
    this.el['win-grade'].textContent = grade;
    this.el['win-stats'].innerHTML = stats;
    this.el['win-line'].textContent = line;
    this.showScreen('win-screen');
  },
  caught(line, tip) {
    if (line) this.el['caught-line'].textContent = line;
    if (tip) this.el['caught-tip'].textContent = tip;
    this.showScreen('caught-screen');
  }
};

export { sleep };

import * as THREE from 'three';
import {
  makePerson, animatePerson, animateKiller, makeKillerModel, makeLabel,
  makeDesk, makeChair, makeTeacherDesk, makeSignPlane, box
} from './props.js';
import { UI, sleep } from './ui.js';

// ─────────────────────────────────────────────────────────────
// small math helpers
// ─────────────────────────────────────────────────────────────
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
const lerp = (a, b, t) => a + (b - a) * t;
const easeInOut = t => t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2;
const easeOut = t => 1 - Math.pow(1 - t, 3);
const easeIn = t => t * t * t;
const smooth = t => t * t * (3 - 2 * t);

function v(x, y, z) { return { x, y, z }; }
function mix(a, b, t) { return v(lerp(a.x, b.x, t), lerp(a.y, b.y, t), lerp(a.z, b.z, t)); }

function rand(a, b) { return a + Math.random() * (b - a); }

// ─────────────────────────────────────────────────────────────
// cinematic engine
// ─────────────────────────────────────────────────────────────
export class Cinematic {
  constructor(game) {
    this.game = game;
    this.active = false;
    this.shots = [];
    this.index = 0;
    this.shotT = 0;
    this.total = 0;
    this.flags = 0;
    this.resolve = null;
    this.name = '';
    this.group = new THREE.Group();
    this.group.name = 'cinematicActors';
    game.scene.add(this.group);
    this.actors = [];
    this.lights = [];
    this.extra = [];
    this._look = new THREE.Vector3();
    this._shakeSeed = Math.random() * 100;
    this._savedFov = 74;
    this._ended = false;
  }

  // ── actor helpers ──────────────────────────────────────────
  person(opts, x, z, yaw = 0) {
    const model = makePerson(opts);
    model.position.set(x, 0, z);
    model.rotation.y = yaw;
    this.group.add(model);
    const actor = {
      model, kind: 'person', x, z, yaw, mode: 'idle', speed: 0, talk: 0,
      talkT: 0, panic: 0, seated: false, gesture: 0, baseX: x, baseZ: z
    };
    this.actors.push(actor);
    return actor;
  }

  killer(x, z, yaw = 0) {
    const model = makeKillerModel();
    model.position.set(x, 0, z);
    model.rotation.y = yaw;
    this.group.add(model);
    const actor = { model, kind: 'killer', x, z, yaw, mode: 'walk', speed: 0 };
    this.actors.push(actor);
    return actor;
  }

  prop(mesh, x, y, z, ry = 0) {
    mesh.position.set(x, y, z);
    mesh.rotation.y = ry;
    this.group.add(mesh);
    return mesh;
  }

  light(color, intensity, dist, x, y, z) {
    const l = new THREE.PointLight(color, intensity, dist, 2);
    l.position.set(x, y, z);
    this.group.add(l);
    this.lights.push(l);
    return l;
  }

  say(actor, text, dur = 2.2) {
    if (!actor) return;
    actor.talk = 1;
    actor.talkT = dur;
  }

  makeAura(color = 0xb9a6ff, scale = 1) {
    const g = new THREE.Group();
    const rings = [];
    for (let i = 0; i < 4; i++) {
      const ring = new THREE.Mesh(
        new THREE.TorusGeometry(0.7 + i * 0.32, 0.014 + i * 0.004, 6, 48),
        new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.55 - i * 0.09, blending: THREE.AdditiveBlending, depthWrite: false })
      );
      ring.rotation.x = Math.PI / 2 + rand(-0.2, 0.2);
      ring.rotation.z = rand(0, 6.28);
      g.add(ring);
      rings.push(ring);
    }
    const positions = new Float32Array(180 * 3);
    for (let i = 0; i < 180; i++) {
      const a = rand(0, Math.PI * 2), r = rand(0.25, 2.2);
      positions[i * 3] = Math.cos(a) * r;
      positions[i * 3 + 1] = rand(-0.1, 3.1);
      positions[i * 3 + 2] = Math.sin(a) * r;
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const pts = new THREE.Points(geo, new THREE.PointsMaterial({
      color, size: 0.055, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false
    }));
    g.add(pts);
    g.scale.setScalar(scale);
    g.userData.rings = rings;
    g.userData.pts = pts;
    return g;
  }

  // ── lifecycle ──────────────────────────────────────────────
  async play(name, buildShots, opts = {}) {
    if (this.active) return false;
    this.active = true;
    this._ended = false;
    this.name = name;
    this.shots = buildShots();
    this.index = 0;
    this.shotT = 0;
    this.total = 0;
    this.flags = 0;
    this.actors = [];
    this.lights = [];
    this.extra = [];
    while (this.group.children.length) this.group.remove(this.group.children[0]);
    this.group.visible = true;

    this.game.state = 'cutscene';
    this.game.setInputActive(false);
    this.game.hideGameplayEntities(true);
    this._savedFov = this.game.camera.fov;
    UI.hideScreens();
    UI.showHud(false);
    UI.showCine(true);
    UI.letterbox(true);
    UI.cineSkip(true);
    UI.down(false);
    UI.el.app.classList.add('cinema');
    try { document.exitPointerLock?.(); } catch {}

    const p = new Promise(res => { this.resolve = res; });
    opts.onStart?.(this);
    this.enterShot(0);
    return p;
  }

  enterShot(i) {
    const shot = this.shots[i];
    if (!shot) return;
    this.shotT = 0;
    this.flags = 0;
    UI.cineHideCard();
    UI.cineGradeHide();
    UI.cineClearSub();
    if (shot.lines) for (const l of shot.lines) l._shown = false;
    if (shot.cards) for (const c of shot.cards) c._shown = false;
    if (shot.flashes) for (const f of shot.flashes) f._shown = false;
    shot.onStart?.(this);
    if (shot.final) {
      // final shot is triggered by its own onStart / onUpdate
    }
  }

  finish(skipped = false) {
    if (!this.active || this._ended) return;
    this._ended = true;
    this.active = false;
    UI.showCine(false);
    UI.letterbox(false);
    UI.cineSkip(false);
    UI.cineLines(false);
    UI.cineFlare(false);
    UI.cineHideCard();
    UI.cineGradeHide();
    UI.cineClearSub();
    UI.el.app.classList.remove('cinema');
    this.game.camera.fov = this._savedFov;
    this.game.camera.updateProjectionMatrix();
    this.game.camera.rotation.z = 0;
    while (this.group.children.length) this.group.remove(this.group.children[0]);
    for (const l of this.lights) { try { l.parent?.remove(l); } catch {} }
    this.lights = [];
    this.actors = [];
    this.game.hideGameplayEntities(false);
    this.game.onCutsceneDone(this.name, skipped);
    const r = this.resolve;
    this.resolve = null;
    if (r) r({ skipped });
  }

  skip() {
    if (!this.active) return;
    this.finish(true);
  }

  update(dt) {
    if (!this.active) return;
    const shot = this.shots[this.index];
    if (!shot) { this.finish(); return; }
    const scale = shot.timeScale ?? 1;
    const sdt = dt * scale;
    this.shotT += sdt;
    this.total += dt;
    const t = clamp(this.shotT / shot.dur, 0, 1);

    // camera motion
    const e = (shot.ease || easeInOut)(t);
    if (shot.cam) shot.cam(this, this.shotT, sdt, t);
    else this.applyCamera(shot, e, t);

    // scheduled films
    if (shot.lines) {
      for (const l of shot.lines) {
        if (!l._shown && this.shotT >= l.at) {
          l._shown = true;
          UI.cineSubtitle(l.who, l.text, l.dur || 3.4);
          this.say(l.actor, l.dur || 2.2);
          if (l.sfx) l.sfx(this.game.audio);
        }
      }
    }
    if (shot.cards) {
      for (const c of shot.cards) {
        if (!c._shown && this.shotT >= c.at) {
          c._shown = true;
          UI.cineCard(c.kicker, c.title, c.align);
          if (c.dur) setTimeout(() => { if (this.active && this.index === this.shots.indexOf(shot)) UI.cineHideCard(); }, c.dur * 1000);
        }
      }
    }
    if (shot.flashes) {
      for (const f of shot.flashes) {
        if (!f._shown && this.shotT >= f.at) {
          f._shown = true;
          UI.cineFlash();
          this.game.audio?.stinger();
        }
      }
    }
    if (shot.onUpdate) shot.onUpdate(this, this.shotT, sdt, t);
    this.updateActors(sdt, shot);

    if (this.shotT >= shot.dur) {
      shot.onEnd?.(this);
      this.index++;
      if (this.index >= this.shots.length) this.finish();
      else this.enterShot(this.index);
    }
  }

  applyCamera(shot, e, t) {
    const cam = this.game.camera;
    const from = shot.from;
    const to = shot.to || shot.from;
    const pos = mix(from, to, e);
    const lookA = shot.lookFrom || from.look || { x: pos.x + Math.sin(pos.ry || 0), y: 1.4, z: pos.z };
    const lookB = shot.lookTo || to.look || lookA;
    const look = mix(lookA, lookB, shot.lookEase ? shot.lookEase(t) : e);
    // handheld drift
    const hand = shot.handheld ?? 0.012;
    const sx = Math.sin(this.total * 0.9 + this._shakeSeed) * hand;
    const sy = Math.cos(this.total * 0.71 + 2.1) * hand;
    const shake = (shot.shake || 0) * (shot.shakeEase ? shot.shakeEase(t) : 1);
    const shx = Math.sin(this.total * 39 + this._shakeSeed) * shake + Math.sin(this.total * 71) * shake * 0.4;
    const shy = Math.cos(this.total * 43 + 1.7) * shake;
    cam.position.set(pos.x + sx + shx, pos.y + sy + shy, pos.z + sx * 0.6 + shx * 0.5);
    this._look.set(look.x + shx * 0.5, look.y + shy * 0.5, look.z);
    cam.lookAt(this._look);
    cam.rotation.z += (shot.roll || 0) * e + Math.sin(this.total * 0.6) * (shot.rollDrift || 0);
    const fov = lerp(shot.fov ?? 55, shot.fovTo ?? shot.fov ?? 55, e);
    cam.fov = fov;
    cam.updateProjectionMatrix();
  }

  updateActors(dt, shot) {
    for (const a of this.actors) {
      if (a.kind === 'person') {
        if (a.talkT > 0) {
          a.talkT -= dt;
          a.talk = Math.max(0, a.talkT > 0 ? 1 : 0);
        } else a.talk = Math.max(0, a.talk - dt * 3);
        animatePerson(a.model, dt, {
          mode: a.mode, speed: a.speed, talk: a.talk, panic: a.panic,
          gesture: a.gesture, crouch: a.seated ? 0.32 : 0
        });
        if (a.seated) {
          const p = a.model.userData.parts;
          if (p) {
            p.hips.position.y = 0.61;
            p.hips.rotation.x = 0;
            p.legL.rotation.x = -1.35;
            p.legR.rotation.x = -1.35;
            p.kneeL.rotation.x = 1.45;
            p.kneeR.rotation.x = 1.45;
          }
        }
        if (a.pose) a.pose(a.model, this.total);
        if (a.talkT > 0) a.model.position.x = a.baseX + Math.sin(this.total * 2.5) * 0.008;
      } else if (a.kind === 'killer') {
        animateKiller(a.model, dt, a.mode, this.total);
        if (a.pose) a.pose(a.model, this.total);
      }
    }
  }
}

