  rainGeo.setAttribute('position', new THREE.BufferAttribute(rp, 3));
  const rain = new THREE.Points(rainGeo, new THREE.PointsMaterial({ color: 0x9ec4e8, size: 0.045, transparent: true, opacity: 0.35, depthWrite: false }));
