const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => { errors.push('PAGEERROR: ' + e.message); console.log('PAGEERROR:', e.message); });
  page.on('console', m => { if (m.type() === 'error') { errors.push('CONSOLE: ' + m.text()); console.log('CONSOLE-ERR:', m.text()); } });
  const shot = async (n) => page.screenshot({ path: `/tmp/opencode/${n}.png` });

  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForTimeout(2600);
  await shot('s-title');
  await page.click('#btn-play');
  await page.waitForTimeout(4200); await shot('s-intro1');
  await page.waitForTimeout(6200); await shot('s-intro2');
  await page.waitForTimeout(5600); await shot('s-intro3');
  await page.waitForTimeout(6500); await shot('s-intro4');
  console.log('state intro', await page.evaluate(() => window.__game.state));
  await page.evaluate(() => window.__game.cinematic.skip());
  await page.waitForTimeout(2200); await shot('s-play');

  await page.evaluate(() => window.__game.damagePlayer(200, null));
  await page.waitForTimeout(1100); await shot('s-jumpscare');
  await page.waitForTimeout(2600); await shot('s-down');
  console.log('state down', await page.evaluate(() => window.__game.state));

  await page.evaluate(() => { window.__game.reviveActive(); window.__game.state = 'play'; });
  await page.waitForTimeout(800);

  await page.evaluate(() => window.__game.startJakeReveal());
  await page.waitForTimeout(4500); await shot('s-jake1');
  await page.waitForTimeout(6000); await shot('s-jake2');
  await page.waitForTimeout(7000); await shot('s-jake3');
  await page.waitForTimeout(5500); await shot('s-jake4');
  await page.waitForTimeout(6000); await shot('s-police1');
  await page.waitForTimeout(5500); await shot('s-police2');
  console.log('final state', await page.evaluate(() => window.__game.state));
  console.log('ERRORS', errors.length);
  await browser.close();
})();

