import * as THREE from 'three';

// ─────────────────────────────────────────────────────────────
// Static visibility culler
//
// Three.js already frustum-culls individual meshes, but it has no
// occlusion culling: desks, lockers, posters and decorations in rooms
// you cannot possibly see still cost draw calls. This pass hides whole
// props when they are outside the camera frustum, or when every sampled
// part of their bounds is behind a wall / closed door.
//
// It is intentionally conservative:
//   • whole props are tested as one unit (no half-desks)
//   • a prop is hidden only after two consecutive fully-blocked sweeps
//   • anything within 6m is always kept visible
//   • only static decoration groups are touched, never gameplay items,
//     characters, doors, bodies or the cinematic layer
// ─────────────────────────────────────────────────────────────
export class VisibilityCuller {
  constructor(game) {
    this.game = game;
    this.camera = game.camera;
    this.frustum = new THREE.Frustum();
    this.projScreen = new THREE.Matrix4();
    this.entries = [];
    this.occluders = [];
    this.timer = 0;
    this.interval = 0.3;
    this.stats = { props: 0, visible: 0, hiddenFrustum: 0, hiddenOccluded: 0 };
    this.box = new THREE.Box3();
    this.sphere = new THREE.Sphere();
    this.tmp = new THREE.Vector3();
  }

  collect() {
    const world = this.game.world;
    const roots = [world.propGroup, world.hideGroup];
    this.entries.length = 0;

    for (const root of roots) {
      for (const obj of root.children) {
        if (!obj || obj.isLight) continue;
        obj.updateWorldMatrix(true, true);
        const box = new THREE.Box3().setFromObject(obj);
        if (box.isEmpty()) continue;
        const sphere = box.getBoundingSphere(new THREE.Sphere());
        if (sphere.radius < 0.05) continue;
        this.entries.push({
          obj, box, sphere,
          radius: sphere.radius,
          cx: sphere.center.x,
          cy: sphere.center.y,
          cz: sphere.center.z,
          blocked: 0,
          hidden: false,
          wasVisible: obj.visible
        });
      }
    }

    // Only walls, doors and large solid blockers can occlude. Decor
    // colliders are usually sight:false, so they are already excluded.
    this.occluders = world.colliders.filter(c =>
      c.enabled !== false && c.sight === true &&
      (c.x2 - c.x1) * (c.z2 - c.z1) > 0.12
    );
    this.stats.props = this.entries.length;
  }

  reset() {
    for (const e of this.entries) {
      e.blocked = 0;
      e.hidden = false;
      e.obj.visible = true;
    }
  }

  // conservative 2D line-of-sight; sampling several points stops props
  // from popping out just because their centre is behind a doorway jamb
  losBlocked(ax, az, bx, bz) {
    for (const c of this.occluders) {
      if (this.segmentAABB(ax, az, bx, bz, c)) return true;
    }
    return false;
  }

  segmentAABB(ax, az, bx, bz, c) {
    // Liang–Barsky clip
    let t0 = 0, t1 = 1;
    const dx = bx - ax, dz = bz - az;
    const p = [-dx, dx, -dz, dz];
    const q = [ax - c.x1, c.x2 - ax, az - c.z1, c.z2 - az];
    for (let i = 0; i < 4; i++) {
      if (p[i] === 0) {
        if (q[i] < 0) return false;
      } else {
        const r = q[i] / p[i];
        if (p[i] < 0) {
          if (r > t1) return false;
          if (r > t0) t0 = r;
        } else {
          if (r < t0) return false;
          if (r < t1) t1 = r;
        }
      }
    }
    return true;
  }

  update(dt) {
    if (!this.entries.length) return;
    this.timer -= dt;
    const inCine = this.game.state === 'cutscene';
    if (this.timer > 0) return;
    this.timer = inCine ? 0.18 : this.interval;

    const cam = this.camera;
    cam.updateMatrixWorld();
    this.projScreen.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
    this.frustum.setFromProjectionMatrix(this.projScreen);
    const camX = cam.position.x, camZ = cam.position.z;
    let visible = 0, hf = 0, ho = 0;

    for (const e of this.entries) {
      // 1) frustum — cheap and exact at prop granularity
      if (!this.frustum.intersectsSphere(e.sphere)) {
        if (!e.hidden) e.obj.visible = false;
        e.hidden = true;
        e.blocked = 0;
        hf++;
        continue;
      }

      // 2) near props are always visible; avoids breathing-pop at doorways
      const dx = e.cx - camX, dz = e.cz - camZ;
      const dist2 = dx * dx + dz * dz;
      if (dist2 < (e.radius + 6) * (e.radius + 6)) {
        e.blocked = 0;
        if (e.hidden) { e.obj.visible = true; e.hidden = false; }
        visible++;
        continue;
      }

      // 3) occlusion — test centre + four inset corners of the bounds.
      //    All five must be blocked before a prop is hidden.
      const min = e.box.min, max = e.box.max;
      const sx = (max.x - min.x) * 0.34;
      const sz = (max.z - min.z) * 0.34;
      const mx = (min.x + max.x) * 0.5;
      const mz = (min.z + max.z) * 0.5;
      let allBlocked = this.losBlocked(camX, camZ, mx, mz);
      if (allBlocked) {
        allBlocked = this.losBlocked(camX, camZ, mx - sx, mz - sz)
          && this.losBlocked(camX, camZ, mx + sx, mz - sz)
          && this.losBlocked(camX, camZ, mx - sx, mz + sz)
          && this.losBlocked(camX, camZ, mx + sx, mz + sz);
      }

      if (allBlocked) {
        e.blocked++;
        if (e.blocked >= 2 && !e.hidden) {
          e.obj.visible = false;
          e.hidden = true;
        }
      } else {
        e.blocked = 0;
        if (e.hidden) { e.obj.visible = true; e.hidden = false; }
      }
      if (e.hidden) ho++; else visible++;
    }

    this.stats.visible = visible;
    this.stats.hiddenFrustum = hf;
    this.stats.hiddenOccluded = ho;
  }
}

