    const p = new THREE.Mesh(new THREE.PlaneGeometry(0.3, 0.38), new THREE.MeshStandardMaterial({
      color: [0xe9e2c8, 0xf0e8b0, 0xd9e0d0][i % 3], roughness: 0.95
