        let vis = o.visible; let p = o.parent;
        while (p) { if (!p.visible) { vis = false; break; } p = p.parent; }
        if (!vis) return;
        if (!o.geometry.boundingSphere) o.geometry.computeBoundingSphere();
        const sph = o.geometry.boundingSphere.clone().applyMatrix4(o.matrixWorld);
        if (!fr.intersectsSphere(sph)) return;
        n++;
      });
      if (n) {
        const label = (child.name || child.type) + ':' + child.id + ':' + (child.userData.cullSkip ? 'skip' : '');
        by[label] = (by[label] || 0) + n;
        total += n;
      }
