enterShot(i) {
  const shot = this.shots[i];
  if (!shot) return;
  this.shotT = 0;
  this.flags = 0;
  UI.cineHideCard();
  UI.cineGradeHide();
  UI.cineClearSub();
  if (shot.lines) for (const l of shot.lines) l._shown = false;
  if (shot.cards) for (const c of shot.cards) c._shown = false;
  if (shot.flashes) for (const f of shot.flashes) f._shown = false;
  shot.onStart?.(this);
  if (shot.final) {
    // final shot is triggered by its own onStart / onUpdate
  }
}

finish(skipped = false) {
  if (!this.active || this._ended) return;
  this._ended = true;
  this.active = false;
  UI.showCine(false);
  UI.letterbox(false);
  UI.cineSkip(false);
  UI.cineLines(false);
  UI.cineFlare(false);
  UI.cineHideCard();
  UI.cineGradeHide();
  UI.cineClearSub();
  UI.el.app.classList.remove('cinema');
  this.game.camera.fov = this._savedFov;
  this.game.camera.updateProjectionMatrix();
  this.game.camera.rotation.z = 0;
  while (this.group.children.length) this.group.remove(this.group.children[0]);
  for (const l of this.lights) { try { l.parent?.remove(l); } catch {} }
  this.lights = [];
  this.actors = [];
  this.game.hideGameplayEntities(false);
  this.game.onCutsceneDone(this.name, skipped);
  const r = this.resolve;
  this.resolve = null;
  if (r) r({ skipped });
}

skip() {
  if (!this.active) return;
  this.finish(true);
}

startJakeReveal(fromEnding = false) {
  if (this._jakeStarted) return;
  this._jakeStarted = true;
  this.state = 'cutscene';
  UI.showHud(false);
  UI.setDown(false);
  audio.setUnderwater(false);
  audio.alarmStop();
  audio.chaseStop();
  this.afterCutscene = () => this.startPoliceEnding();
  setTimeout(() => {
    this.cinematic.play('jake', () => jakeRevealShots(this.cinematic));
  }, 650);
},

startPoliceEnding() {
  if (this._policeStarted) return;
  this._policeStarted = true;
  UI.fade(false, 700);
  this.state = 'cutscene';
  this.afterCutscene = () => this.showWin();
  setTimeout(() => {
    this.cinematic.play('police', () => policeShots(this.cinematic));
  }, 300);
},

showWin() {
  if (this.state === 'win') return;
  this.state = 'win';
  UI.showHud(false);
  UI.showCine(false);
  UI.letterbox(false);
  UI.setDown(false);
  audio.setUnderwater(false);
  audio.stopAmbience();
  audio.alarmStop();
  audio.chaseStop();
  audio.win();
  this.pendingSwitch = 0;
  UI.fade(false, 800);
  const minutes = Math.floor((performance.now() - this.stats.started) / 60000);
  const secs = Math.floor(((performance.now() - this.stats.started) % 60000) / 1000);
  const survivors = this.bots.filter(b => b.escaped).length + (this.player.escaped ? 1 : 0);
  const stats = `KEYS RECOVERED: ${this.player.keys.size} / 8<br>CROWBAR: ${this.player.crowbar ? 'YES' : 'NO'}<br>JOKE NOTES: ${this.player.notes} / 7<br>SURVIVORS: ${survivors}<br>TIME: ${minutes}m ${String(secs).padStart(2, '0')}s`;
  UI.win('FINAL GRADE: Q+', stats, survivors >= 2 ? 'You reached the police station with people. The report cards did not survive.' : 'You reached the police station. The group chat will never recover.');
},

