cd /tmp/opencode && cat > bench.cjs <<'EOF'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--ignore-gpu-blocklist'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.setDefaultTimeout(150000);
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('http://localhost:8123/', { waitUntil: 'load' });
  await page.waitForTimeout(2800);
  await page.click('#btn-play');
  await page.waitForTimeout(1200);
  await page.evaluate(() => window.__game.cinematic.skip());
  await page.waitForTimeout(1200);
  const spots = [
    ['classroom', -6.6, 4.4, Math.PI],
    ['corridor', -20, 0, -Math.PI/2],
    ['gym', 12, -8, -1.9],
    ['cafeteria', -25, 10, Math.PI/2 + 0.4],
    ['outdoor', 90, 0, Math.PI/2],
  ];
  for (const [name, x, z, yaw] of spots) {
    const on = await page.evaluate(async ([x, z, yaw]) => {
      const g = window.__game;
      g.world.setLighting('day');
      g.player.pos.set(x, 0, z); g.camYaw = yaw; g.pitch = 0;
      g.updateCamera(0.016);
      g.culler.enabled = true; g.culler.lastSweep = -1; g.culler.lastCamArea = null;
      g.culler.update(0.016);
      g.renderer.render(g.scene, g.camera);
      return { calls: g.renderer.info.render.calls, tris: g.renderer.info.render.triangles,
               visible: g.culler.stats.visible, hiddenArea: g.culler.stats.hiddenArea,
               archHidden: g.culler.stats.archHidden, areas: g.culler.stats.areasVisible };
    }, [x, z, yaw]);
    const off = await page.evaluate(() => {
      const g = window.__game;
      g.culler.enabled = false;
      g.culler.entries.forEach(e => { e.obj.visible = true; });
      g.culler.arch.forEach(e => { if (!e.cullSkip) e.obj.visible = true; });
      g.renderer.render(g.scene, g.camera);
      const r = { calls: g.renderer.info.render.calls, tris: g.renderer.info.render.triangles };
      g.culler.enabled = true; g.culler.lastSweep = -1;
      return r;
    });
    console.log(name.padEnd(10), 'culled', String(on.calls).padStart(4), 'calls /', String(on.tris).padStart(6), 'tris   unculled', String(off.calls).padStart(4), '/', String(off.tris).padStart(6),
      ` (props ${on.visible}/848, arch ${on.archHidden}/316 hidden)`);
  }
  await browser.close();
})();
EOF
