from pathlib import Path
p=Path('src/culling.js'); s=p.read_text()
s=s.replace("""    const cam = this.camera;
    cam.updateMatrixWorld();
    this.proj.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
    this.frustum.setFromProjectionMatrix(this.proj);""",
"""    const cam = this.camera;
    cam.updateMatrixWorld();
    // the renderer refreshes matrixWorldInverse, but we run before it —
    // and after a POV switch / camera cut that matrix is from the old
    // view, which would cull against the wrong place. Rebuild it here.
    cam.matrixWorldInverse.copy(cam.matrixWorld).invert();
    this.proj.multiplyMatrices(cam.projectionMatrix, cam.matrixWorldInverse);
    this.frustum.setFromProjectionMatrix(this.proj);""")
p.write_text(s)
PY
